(window.__quranSurahs=window.__quranSurahs||{})[85]={"nomPhon":"Al-Burooj","versets":{"1":{"text":"Par le ciel aux constellations!","arabe":"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ"},"2":{"text":"et par le jour promis!","arabe":"وَٱلْيَوْمِ ٱلْمَوْعُودِ"},"3":{"text":"et par le témoin et ce dont on témoigne!","arabe":"وَشَاهِدٍۢ وَمَشْهُودٍۢ"},"4":{"text":"Périssent les gens de l'Uhdûd,","arabe":"قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ"},"5":{"text":"par le feu plein de combustible,","arabe":"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ"},"6":{"text":"cependant qu'ils étaient assis tout autour,","arabe":"إِذْ هُمْ عَلَيْهَا قُعُودٌۭ"},"7":{"text":"ils étaient ainsi témoins de ce qu'ils faisaient des croyants,","arabe":"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ"},"8":{"text":"à qui ils ne leur reprochaient que d'avoir cru en Allah, le Puissant, le Digne de louange,","arabe":"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ"},"9":{"text":"Auquel appartient la royauté des cieux et de la terre. Allah est témoin de toute chose.","arabe":"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ"},"10":{"text":"Ceux qui font subir des épreuves aux croyants et aux croyantes, puis ne se repentent pas, auront le châtiment de l'Enfer et le supplice du feu.","arabe":"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ"},"11":{"text":"Ceux qui croient et accomplissent les bonnes œuvres auront des Jardins sous lesquels coulent les ruisseaux. Cela est le grand succès.","arabe":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ"},"12":{"text":"La riposte de ton Seigneur est redoutable.","arabe":"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ"},"13":{"text":"C'est Lui, certes, qui commence (la création) et la refait.","arabe":"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ"},"14":{"text":"Et c'est Lui le Pardonneur, le Tout-Affectueux,","arabe":"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ"},"15":{"text":"Le Maître du Trône, le Tout-Glorieux,","arabe":"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ"},"16":{"text":"Il réalise parfaitement tout ce qu'Il veut.","arabe":"فَعَّالٌۭ لِّمَا يُرِيدُ"},"17":{"text":"T'est-il parvenu le récit des armées,","arabe":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ"},"18":{"text":"de Pharaon, et de Thamûd?","arabe":"فِرْعَوْنَ وَثَمُودَ"},"19":{"text":"Mais ceux qui ne croient pas persistent à démentir,","arabe":"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ"},"20":{"text":"alors qu'Allah, derrière eux, les cerne de toutes parts.","arabe":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ"},"21":{"text":"Mais c'est plutôt un Coran glorifié","arabe":"بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ"},"22":{"text":"préservé sur une Tablette (auprès d'Allah).","arabe":"فِى لَوْحٍۢ مَّحْفُوظٍۭ"}}};